  const verb = match[1] === "Running" ? form === "one" ? "\u0412\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F" : "\u0412\u044B\u043F\u043E\u043B\u043D\u044F\u044E\u0442\u0441\u044F" : form === "one" ? "\u0412\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0430" : "\u0412\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043E";
