var plural2 = (n, one, few, many) => {
  const value2 = Math.abs(Number(n)), last = value2 % 10, lastTwo = value2 % 100;
  return last === 1 && lastTwo !== 11 ? one : last >= 2 && last <= 4 && (lastTwo < 12 || lastTwo > 14) ? few : many;
};
