var plural7 = (n, one, few, many) => {
  const value2 = Math.abs(Number(n));
  const last = value2 % 10;
  const lastTwo = value2 % 100;
  return last === 1 && lastTwo !== 11 ? one : last >= 2 && last <= 4 && (lastTwo < 12 || lastTwo > 14) ? few : many;
};
var tools = (n) => `${n} ${plural7(n, "\u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442", "\u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u0430", "\u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u043E\u0432")}`;
