  const attachedComposer = `${consentDrawer}:not([data-collapsed]) + [data-slot="composer-root"]`;
  const draftConsentDock = `${dock2}:has(> [data-hcv-draft-bar] + .status-drawer:not([data-collapsed])):is(:has(> .status-drawer [data-slot="status-stack-content"] > ${statusSection}:only-child > ${consentIcon}), :has(> .status-drawer [data-slot="status-stack-content"] > ${statusSection}:first-child > ${consentIcon}):has(> .status-drawer [data-slot="status-stack-content"] > ${statusSection}:last-child:nth-child(2) > ${subagentRoster}))`;
